                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.freakins_DB_Product_FACEBOOK_CONSOLIDATED AS select Adset_Name ,Adset_ID ,FB.ad_id ,FB.ad_name ,\'FACEBOOK FREAKINS\' as Account_Name ,lower(trim(SPLIT(FB.product_id, \',\')[OFFSET(0)])) product_id ,Account_ID ,Campaign_Name ,Campaign_ID ,cast(Fb.date_start as date) Date ,SUM(CLICKS) Clicks ,sum(ifnull(inline_link_clicks,0)) Link_Clicks ,SUM(SPEND) Spend ,SUM(IMPRESSIONS) Impressions ,SUM(ifnull(Fc.Conversions,0)) Conversions ,sum(ifnull(reach,0)) reach ,sum(ifnull(frequency,0)) as frequency ,SUM(ifnull(Fcv.Conversion_Value,0)) Conversion_Value ,sum(ifnull(fd.add_to_carts,0)) Add_to_carts ,sum(ifnull(fdv.add_to_cart_value,0)) Add_to_cart_value ,sum(ifnull(fe.landing_page_views,0)) Landing_page_views ,sum(ifnull(ff.initiate_checkouts,0)) Initiate_checkouts ,sum(ifnull(ffv.initiate_checkouts_value,0)) Initiate_checkouts_value ,\'FACEBOOK\' Channel ,\'FACEBOOK\' Account ,fm.product_type category ,fm.style_code ,fm.variant_id from `MapleMonk.freakins_db_product_customcampaigns_data` FB left join ( select ad_id ,ad_name ,date_start ,SUM(ifnull(cast(JSON_EXTRACT_SCALAR(C,\'$.7d_click\') as FLOAT64),0) + ifnull(cast(JSON_EXTRACT_SCALAR(C,\'$.1d_view\') as FLOAT64),0)) Conversions from maplemonk.freakins_db_product_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start )Fc ON Fb.ad_id = Fc.ad_id and Fb.date_start=Fc.date_start left join ( select ad_id ,ad_name ,date_start ,SUM(ifnull(cast(JSON_EXTRACT_SCALAR(CV,\'$.7d_click\') as FLOAT64),0) + ifnull(cast(JSON_EXTRACT_SCALAR(CV,\'$.1d_view\') as FLOAT64),0)) Conversion_Value from maplemonk.freakins_db_product_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start )Fcv ON Fb.ad_id = Fcv.ad_id and Fb.date_start=Fcv.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) add_to_carts from maplemonk.freakins_db_product_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fd ON Fb.ad_id = Fd.ad_id and Fb.date_start=Fd.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Add_to_cart_Value from maplemonk.freakins_db_product_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Fdv ON Fb.ad_id = Fdv.ad_id and Fb.date_start=Fdv.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Landing_page_views from maplemonk.freakins_db_product_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'landing_page_view\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fe ON Fb.ad_id = Fe.ad_id and Fb.date_start=Fe.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Initiate_checkouts from maplemonk.freakins_db_product_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Ff ON Fb.ad_id = Ff.ad_id and Fb.date_start=Ff.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Initiate_checkouts_Value from maplemonk.freakins_db_product_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Ffv ON Fb.ad_id = Ffv.ad_id and Fb.date_start=Ffv.date_start left join ( select * from MapleMonk.FREAKINS_FINALL_SKU_MASTER qualify row_number() over(partition by lower(Product_ID) order by 1) = 1 )Fm on lower(trim(SPLIT(FB.product_id, \',\')[OFFSET(0)])) = LOWER(TRIM(SPLIT(Fm.Product_Id, \'-\')[OFFSET(ARRAY_LENGTH(SPLIT(Fm.Product_Id, \'-\')) - 1)])) group by Adset_Name, Adset_ID,fb.ad_id,fb.product_id,fb.AD_NAME, Account_Name, Account_ID, Campaign_Name, Campaign_ID,Fb.date_start,fm.product_type,fm.style_code,fm.variant_id ;",
